package com.example.markscalculate;
import android.os.Bundle; import android.view.View; import android.widget.EditText; import android.widget.TextView; import androidx.appcompat.app.AppCompatActivity;
public class MainActivity extends AppCompatActivity { @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);} public void calculateMarks(View v){EditText a=findViewById(R.id.etEnglishMarks),m=findViewById(R.id.etMathMarks),s=findViewById(R.id.etScienceMarks); TextView r=findViewById(R.id.tvResult); String x=a.getText().toString().trim(),y=m.getText().toString().trim(),z=s.getText().toString().trim(); if(!x.isEmpty()&&!y.isEmpty()&&!z.isEmpty()){int total=Integer.parseInt(x)+Integer.parseInt(y)+Integer.parseInt(z); double avg=total/3.0; r.setText("Total Marks : "+total+"\nAverage Marks : "+avg);}else r.setText("Please enter the marks of all subjects.");}}
